<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import { useAccountSecurity } from '@/composables/useAccountSecurity'
const { t } = useI18n()
const { settings, mode, pending, busy, error, uncertain, qr, form, remaining, needsCode, passwordMode, reload, open, close, submit, confirm, cancel } = useAccountSecurity()
</script>
<template>
  <section class="security-page">
    <header><h1>{{ t('auth.accountSecurity') }}</h1><el-button :disabled="busy" @click="reload">{{ t('auth.refreshSecurity') }}</el-button></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <p v-if="settings && !settings.setupAvailable" role="status">{{ t('auth.securityUnavailable') }}</p>
    <template v-if="settings">
      <el-card shadow="never"><h2>{{ t(settings.totpEnabled ? 'auth.totpEnabled' : 'auth.totpDisabled') }}</h2><p>{{ t('auth.totpDescription') }}</p><p>{{ t('auth.securityNoRecovery') }}</p><p v-if="settings.totpPending && !pending">{{ t('auth.securityPending') }}</p><div class="actions"><el-button type="primary" :disabled="busy || uncertain || !settings.setupAvailable || !!pending" @click="open('enroll')">{{ t(settings.totpEnabled ? 'auth.replaceTotp' : 'auth.bindTotp') }}</el-button><el-button v-if="settings.totpEnabled" :disabled="busy || uncertain || !settings.setupAvailable || !!pending" @click="open('disable')">{{ t('auth.disableTotp') }}</el-button></div></el-card>
      <el-card shadow="never"><h2>{{ t(settings.securityPasswordSet ? 'auth.securityPasswordSet' : 'auth.securityPasswordUnset') }}</h2><p>{{ t('auth.securityPasswordHint') }}</p><div class="actions"><el-button type="primary" :disabled="busy || uncertain || !settings.setupAvailable || !!pending" @click="open(settings.securityPasswordSet ? 'change' : 'set')">{{ t(settings.securityPasswordSet ? 'auth.changeSecurityPassword' : 'auth.setSecurityPassword') }}</el-button><el-button v-if="settings.securityPasswordSet && settings.totpEnabled" :disabled="busy || uncertain || !settings.setupAvailable || !!pending" @click="open('reset')">{{ t('auth.resetSecurityPassword') }}</el-button></div><p v-if="settings.securityPasswordSet">{{ t('auth.securityResetHint') }}</p></el-card>
      <el-card v-if="mode" shadow="never"><form @submit.prevent="submit"><h2>{{ t(mode === 'disable' ? 'auth.disableTotpConfirm' : mode === 'enroll' ? (settings.totpEnabled ? 'auth.replaceTotp' : 'auth.bindTotp') : mode === 'set' ? 'auth.setSecurityPassword' : mode === 'change' ? 'auth.changeSecurityPassword' : 'auth.resetSecurityPassword') }}</h2><p>{{ t('auth.securityWriteHint') }}</p>
        <label for="security-login-password">{{ t('auth.loginPassword') }}</label><el-input id="security-login-password" v-model="form.password" type="password" show-password maxlength="128" autocomplete="current-password" :disabled="busy" />
        <template v-if="needsCode"><label for="security-code">{{ t('auth.totpCode') }}</label><el-input id="security-code" v-model="form.code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" :disabled="busy" /></template>
        <template v-if="mode === 'change'"><label for="security-old">{{ t('auth.oldSecurityPassword') }}</label><el-input id="security-old" v-model="form.oldPassword" type="password" show-password maxlength="8" autocomplete="off" :disabled="busy" /></template>
        <template v-if="passwordMode"><label for="security-new">{{ t('auth.newSecurityPassword') }}</label><el-input id="security-new" v-model="form.newPassword" type="password" show-password maxlength="8" autocomplete="new-password" :disabled="busy" /><label for="security-confirm">{{ t('auth.confirmSecurityPassword') }}</label><el-input id="security-confirm" v-model="form.confirmation" type="password" show-password maxlength="8" autocomplete="new-password" :disabled="busy" /></template>
        <div class="actions"><el-button native-type="submit" type="primary" :disabled="busy || uncertain" :loading="busy">{{ t('auth.saveSecurity') }}</el-button><el-button :disabled="busy" @click="close">{{ t('auth.closeSecurityForm') }}</el-button></div>
      </form></el-card>
      <el-card v-if="pending" shadow="never"><h2>{{ t('auth.confirmEnrollment') }}</h2><p>{{ t('auth.scanAuthenticator') }}</p><img v-if="qr" :src="qr" :alt="t('auth.authenticatorQr')" width="220" height="220" /><label for="manual-secret">{{ t('auth.manualSecret') }}</label><el-input id="manual-secret" :model-value="pending.secret" readonly autocomplete="off" spellcheck="false" /><p role="timer" aria-live="off">{{ t('auth.secondsLeft', { seconds: remaining }) }}</p><form @submit.prevent="confirm"><label for="new-authenticator-code">{{ t('auth.newAuthenticatorCode') }}</label><el-input id="new-authenticator-code" v-model="form.newCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" :disabled="busy" /><div class="actions"><el-button native-type="submit" type="primary" :disabled="busy || uncertain || !remaining">{{ t('auth.confirmEnrollment') }}</el-button><el-button :disabled="busy || uncertain" @click="cancel">{{ t('auth.cancelEnrollment') }}</el-button></div></form></el-card>
    </template>
  </section>
</template>
<style scoped>.security-page{max-width:760px;display:grid;gap:18px}header,.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}h1{font-size:20px;margin:0}h2{font-size:16px}p{line-height:1.6;color:var(--el-text-color-secondary)}label{display:block;margin:16px 0 8px}.actions{justify-content:flex-start;margin-top:16px}.actions :deep(.el-button){margin-left:0}img{max-width:100%;height:auto}</style>
